WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (587, '3', 'ASK 587: a judge is not removed for a defect of the engine''s own making (form fixes of run 42071, A to E)',
  $t$A judge is not sent back, counted, or removed for a defect of the engine's own making, and a judge's RESULT is not raised to a challenger win past a counted challenger break. Five such defects were found in run 42071: the 1,500-character cut and the splice; the own-words check; the keystone label that cannot exist; the second reading reversing the first; the RESULT written as CHALLENGER WINS beside a counted challenger break. A real fault of the same kind is still raised. (plan rev 3, section 1)$t$,
  'in part',
  $t$Written by W4 on the card "Write ASK 587" pressed 23:17 CST 2026-11-23 in W4's thread, with no run live (last execution 42071) (Wall 11360; audit 41171). One write of the engine and the child together: engine moMxiV4Irg1uRBZN 196402d0 to 7536d7bf-06ad-44b1-b852-aaab6388ee2c (Shared Library d749630c to 752887af, 1,174,075 characters; Reread Record 3f7bdf9e to 9d506a0f; Alt Reread Record e56f5714 to 4283a2e0); child MqQHRl7mQQ0z8QdT f900375e to a7113b8d-3379-48ce-944c-a40f6f4eb5c9 (Shared Library 6d92bf4e to 3159ff7d; R2 Alt Reread Record 36a70121 to f6e6bbaa). Items: A the checks read the judge's whole line, not the 1,500-character copy (A3: a cut-marked line makes no E-COL item); B the own-words check; C1 the keystone label; C2 the second reading; D the counted unnamed challenger break reaches every RESULT path (the v25 line, the v61 tag, the gate recompute) and the standing rule (LIB 1345) is unchanged; E no UNREAD COUNTED LINE from a send-back item line. W1 readback MATCH (Wall 11361): versionId and activeVersionId 7536d7bf and a7113b8d; 0 nodes differ from the graded targets; only the five planned nodes changed against the prior live; no model setting or credential changed; library sha f45effef8ec77157 in both. IN PART, because every EXPECT line A to E is unexercised until a run holds its case (plan section 8). Shown offline only: t586 40 PASS, ALL PASS, rerun by W1; the built sbApply2024 run on stored judgment 1273 (live CHALLENGER WINS, target UNDERDETERMINED); the scope check (engine 64 sources 93 uses, child 62 sources 92 uses, 0 out of scope). The plan went through four revisions: rev 0 graded by W1 with D failed (F1, as the plan states of Wall 11330); rev 1 and rev 2 each returned on D (Wall 11342 F1, Wall 11354 D4, as the plan states); rev 3 PASS (Wall 11357), in which W1 withdrew its own 11354 F2 as a mistake of reading scope in plain LIB order. Stated limit of D (plan section 3 item 7): a false closing-contradiction flag now also blocks CHALLENGER WINS on BROKEN. Split out of this ASK to their own: B1 (ASK 550 line), B3 (gemini's three results), B4 (gate refusal counted UNCURED), and G1 to G8 for the operator.$t$,
  '11355, 11357, 11360, 11361',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$No sentence of the operator on ASK 587 is in the record W3 read for this row. His part is the card press: "Write ASK 587", 23:17 CST 2026-11-23, W4's thread (Wall 11360; audit 41171). His statement of 23:00 CST in the W3 thread ("this next fix will mostly be around the judges reasoning...") is the reason the form fixes were split from ASK 586 into ASK 587 (plan587.md head).$t$::text),
  $j${"answer": "Write ASK 587", "source": "Wall 11360; audit 41171", "thread": "W4", "press_time": "23:17 CST", "question": "not in the record W3 read (the card is in W4's thread; Wall 11360 gives its label only)"}$j$::jsonb,
  'W4',
  $j${"md5": "903faa78", "note": "rev 3; rev 1 kept as plan587_rev1.md 30b72a6c, rev 2 as plan587_rev2.md d974b63c; rev 0 was ask586/w4/plan586.md 4a9ecc3e", "path": "ask587/w4/plan587.md", "commit": "52c017f4", "source": "md5sum by W3 (903faa782cd2fd740229720eaf7e099a); Wall 11355, 11357"}$j$::jsonb,
  $j$[{"md5": "d643fc34", "path": "target_engine_586 (build target, engine)", "note": "the engine as built; graded and read back node by node", "source": "plan section 5; Wall 11355, 11357, 11361"}, {"md5": "4476e122", "path": "target_child_586 (build target, child)", "note": "the child as built", "source": "plan section 5; Wall 11355, 11357, 11361"}, {"md5": "3f4e28bf", "path": "a586_w4/build/build586.cjs", "note": "the build script", "source": "plan section 5; not md5-checked by W3 (git only)"}, {"md5": "597906b4", "path": "a586_w4/build/t586.cjs", "note": "the test, 40 cases", "source": "plan section 6; Wall 11355"}, {"md5": "486a114e", "path": "ask587/w4/write/t586_at_write.txt", "note": "t586 output on the fresh fetch at the write; the same md5 as out_t586.txt in the plan", "source": "md5sum by W3 (486a114e98cb07091e5fbc75446764f5)"}, {"md5": "18b43d2a", "path": "gatefn.cjs", "note": "sbApply2024 run in its built scope", "source": "plan section 3b"}, {"md5": "3fd8778f", "path": "scope587.cjs", "note": "acorn scope check", "source": "plan section 3b"}, {"md5": "fa65147f", "path": "ask587/w4/write/put_eng587.json", "note": "PUT body, engine", "source": "md5sum by W3"}, {"md5": "94519e1b", "path": "ask587/w4/write/put_child587.json", "note": "PUT body, child", "source": "md5sum by W3"}, {"md5": "20538828", "path": "ask587/w4/write/fetchback_eng587.json", "note": "fetch-back, engine", "source": "md5sum by W3"}, {"md5": "9fcdb69e", "path": "ask587/w4/write/fetchback_child587.json", "note": "fetch-back, child", "source": "md5sum by W3"}, {"md5": "28604493", "path": "ask587/w4/write/prewrite_eng587.json", "note": "fresh fetch before the write; the same md5 as ask585/w4/write/fetchback_eng585.json (row 153)", "source": "md5sum by W3"}, {"md5": "dd4fd85c", "path": "ask587/w4/write/prewrite_child587.json", "note": "fresh fetch before the write, child", "source": "md5sum by W3"}, {"md5": "12182948", "path": "ask587/w4/write/write587.sh", "note": "the write script", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"copy": "put back the engine and the child together: ask587/w4/write/revert_eng587.json 53f685b4 (the same md5 as ask585/w4/write/put_eng585.json, the ASK 585 PUT body) and revert_child587.json 4fe23222", "path": "ask587/w4/write/revert_eng587.json; ask587/w4/write/revert_child587.json", "source": "Wall 11360 item 7; plan section 10 item 5; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (plan rev 3; it also withdraws W1's own 11354 F2)", "wall_id": 11357, "md5_graded": "903faa78", "verdict_norm": "PASS", "source": "Wall 11357 head"}, {"seat": "W1", "verdict": "PASS (the engine build target: W1 reran the build from W4's files, \"The build gives engine d643fc34 and child 4476e122 again\"; scope check and t586 rerun)", "wall_id": 11357, "md5_graded": "d643fc34", "verdict_norm": "PASS", "source": "Wall 11357 item 2"}, {"seat": "W1", "verdict": "PASS (the child build target, the same item)", "wall_id": 11357, "md5_graded": "4476e122", "verdict_norm": "PASS", "source": "Wall 11357 item 2"}]$j$::jsonb,
  ARRAY['d643fc34','4476e122'], '[41171]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "after": "7536d7bf-06ad-44b1-b852-aaab6388ee2c, active, 398 nodes", "before": "196402d0"}, {"kind": "n8n node", "name": "Shared Library (engine)", "after": "752887af, 1,174,075 characters", "before": "d749630c, 1,171,824 characters"}, {"kind": "n8n node", "name": "Reread Record (engine)", "after": "9d506a0f", "before": "3f7bdf9e"}, {"kind": "n8n node", "name": "Alt Reread Record (engine)", "after": "4283a2e0", "before": "e56f5714"}, {"kind": "n8n workflow", "name": "child MqQHRl7mQQ0z8QdT", "after": "a7113b8d-3379-48ce-944c-a40f6f4eb5c9, active, 156 nodes", "before": "f900375e"}, {"kind": "n8n node", "name": "Shared Library (child)", "after": "3159ff7d, 1,173,896 characters", "before": "6d92bf4e"}, {"kind": "n8n node", "name": "R2 Alt Reread Record (child)", "after": "f6e6bbaa", "before": "36a70121"}]$j$::jsonb,
  $j$[{"name": "t586.cjs, 40 cases (criteria C1 to C7)", "result": "40 PASS, ALL PASS; rerun by W1; rerun on the fresh fetch at the write", "source": "plan section 6; Wall 11357 item 2c; Wall 11360 item 4"}, {"name": "gatefn.cjs: the built sbApply2024 on stored judgment 1273 with a confirmed challenger C1 break", "result": "live CHALLENGER WINS (RESULT DIFFERS, not applied); target UNDERDETERMINED (S1 applied), no ReferenceError; control with no confirmed break: live and target agree", "source": "plan section 3b item 3; Wall 11355 item 3"}, {"name": "scope587.cjs (acorn) on every joined source", "result": "engine 64 sources, 93 uses; child 62 sources, 92 uses; 0 out of scope", "source": "Wall 11355 item 4; W1's own run Wall 11357 item 2b"}, {"name": "C8 at the write: fresh fetch equal to the build base; per-node diff of the fetch-backs; Library Check pair", "result": "fetch equal in every node and the connections; each fetch-back equals its PUT body; only the five nodes changed; pair LIB f45effef8ec77157, MAP b0d91d9c30aa1654 PASSES", "source": "Wall 11360 items 4, 5"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (fresh fetch 23:18 CST: engine versionId and activeVersionId 7536d7bf, 398 nodes; child a7113b8d, 156 nodes; 0 nodes differ from the graded targets; only the five planned nodes changed against 196402d0 and f900375e; connections unchanged; no model setting or credential changed; library sha f45effef8ec77157 in both; audit row 41171 present)", "wall_id": 11361}]$j$::jsonb,
  $j${"case": "UNEXERCISED. EXPECT lines of plan section 8 for the next run: A, a flagged_line over 1,500 characters is stored whole and no E-COL send-back reads \"no deciding step\" on a line that carries \"-- WHY IT FAILS:\"; A3, no E-COL item for a line ending \" [...]\"; B, an E-COL KEEP quoting the answering side's own unquoted sentence is CURED with \"quotes the answer\"; C1, no pkgLAY KEYSTONE item \"names no collision line of D<k>\" when the judge wrote no \"D<k> vs C\" line; C2, an E-REREAD row whose changed line carries the first reading's grade reads RECORD-ONLY; D, an AUDIT v25 line with \"counted as one CHALLENGER LINK BROKEN\" has a RECOMPUTED RESULT that is not CHALLENGER WINS and the same seat's last AUDIT v61 WORD is not CHALLENGER WINS; E, removed_rules carries no \"UNREAD COUNTED LINE\" from a SEND-BACK ITEM line.", "source": "plan section 8; Wall 11360 item 8; Wall 11361"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet: W3 owes the entry for items A to E; no manual write while the run of 23:13 CST 2026-11-23 is live (coordinator's order)"}$j$::jsonb,
